31	/*
32	 * @brief: Calculate reduce cof value
33	 * @param [in] input_shape: gert::Shape, the input shape for reduce
34	 * @param [in] reduce_axis: const std::vector<int32_t>, the reduce axes num
35	 * @param [out] reduce_mean_cof: the result of reduce cof value
36	 * @return bool: true or false;
37	 */
38	template <typename T>
39	static inline bool CalcReduceMeanCof(const gert::Shape& input_shape, const std::vector<T>& reduce_axis,
40	                                     float& reduce_mean_cof)
41	{
42	    const size_t dim_len = input_shape.GetDimNum();
43	    const size_t ori_reduce_axis_len = reduce_axis.size();
44	    // init reduce_mean_cof is 1.0
45	    reduce_mean_cof = 1.0;
46	    for (size_t i = 0; i < ori_reduce_axis_len; i++) {
47	        OP_CHECK_IF(!Ops::Nn::IsDimValid(dim_len, reduce_axis[i]),
48	                    OP_LOGE("CalcReduceMeanCof", "%s",
49	                            Ops::Nn::GenInvalidDimMsg("reduce_axis", i, dim_len, reduce_axis[i]).c_str()),
50	                    return false);
51	
52	        // convert reduce axis (like: -1 -> (dim_len - 1))
53	        T single_reduce_axis = reduce_axis[i] < 0 ? reduce_axis[i] + dim_len : reduce_axis[i];
54	
55	        int64_t reduce_dim = input_shape.GetDim(single_reduce_axis);
56	        OP_CHECK_IF(reduce_dim == 0, OP_LOGI("CalcReduceMeanCof", "the reduce dim is 0, will ignore reduce_mean_cof"),
57	                    return true);
58	        if (reduce_dim != 0) {
59	            reduce_mean_cof = reduce_mean_cof / reduce_dim;
60	        }
61	    }
62	    OP_LOGD("CalcReduceMeanCof", "CalcReduceMeanCof cof is %1f", reduce_mean_cof);
63	
64	    return true;
65	}
66	
67	/*
68	 * @brief: add reduce cof value after the tiling data
69	 * @param [in] input_shape: gert::Shape, the input shape for reduce
70	 * @param [in] input_dtype: ge::DataType,  the input dtype for reduce
71	 * @param [in] reduce_axis: const std::vector<int32_t>, the reduce axes num
72	 * @param [out] tiling_data: gert::TilingData, the tiling data, will add the cof value to th lasy TilingData
73	 * @return bool: true or false;
74	 */
75	template <typename T>
76	static inline bool AddReduceMeanCof(const gert::Shape& input_shape, const ge::DataType input_dtype,
77	                                    const std::vector<T>& reduce_axis, gert::TilingData* tiling_data)
78	{
79	    float reduce_mean_cof = 1.0;
80	    bool calcu_flag = CalcReduceMeanCof(input_shape, reduce_axis, reduce_mean_cof);
81	    OP_LOGD("AddReduceMeanCof", "AddReduceMeanCof dtype is %s", Ops::Base::ToString(input_dtype).c_str());
82	    switch (input_dtype) {
83	        case ge::DT_FLOAT:
84	            tiling_data->Append((float)reduce_mean_cof);
85	            return calcu_flag;
86	        case ge::DT_FLOAT16:
87	            tiling_data->Append((Ops::Base::fp16_t)reduce_mean_cof);
88	            tiling_data->Append((uint16_t)0);
89	            return calcu_flag;
90	        default:
91	            OP_LOGW("AddReduceMeanCof", "Only support [DT_FLOAT, DT_FLOAT16], but is [%s]",
92	                    Ops::Base::ToString(input_dtype).c_str());
93	            return false;
94	    }
95	}
