97	template <typename T>
98	class OpHashInput {
99	public:
100	    OpHashInput(const OpHashInput& rhs) { content = rhs.content; }
101	    OpHashInput() {}
102	
103	    explicit OpHashInput(T& input) { content = input; }
104	
105	    OpHashInput& operator=(const OpHashInput& rhs)
106	    {
107	        content = rhs.content;
108	        return *this;
109	    }
110	
111	    bool operator==(const OpHashInput& input) const
112	    {
113	        if (std::memcmp(&content, &input.content, sizeof(content)) == 0) {
114	            return true;
115	        }
116	        return false;
117	    }
118	
119	private:
120	    T content;
121	};
122	} // namespace optiling
